import{_ as t}from"./chunks/qr_ob1_debug.BFcqNe1b.js";import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r,o as i,c as n,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"G6, ONE","description":"","frontmatter":{"source_hash":"a64d69be78","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/troubleshoot/g6.md","filePath":"fr/troubleshoot/g6.md"}'),l={name:"fr/troubleshoot/g6.md"};function o(u,e,d,c,p,m){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="g6-one-troubleshooting" tabindex="-1">Dépannage G6, ONE <a class="header-anchor" href="#g6-one-troubleshooting" aria-label="Permalink to &quot;Dépannage G6, ONE {#g6-one-troubleshooting}&quot;">​</a></h1><p>Si ce n&#39;est pas déjà fait, consultez d&#39;abord <a href="./../install/g6.html">comment configurer le G6/ONE</a>. Cette page traite des problèmes courants une fois la connexion établie, ou de ceux qui empêchent toute connexion.</p><h2 id="no-connectivity-at-all" tabindex="-1">Aucune connectivité <a class="header-anchor" href="#no-connectivity-at-all" aria-label="Permalink to &quot;Aucune connectivité {#no-connectivity-at-all}&quot;">​</a></h2><ol><li>Partez des <a href="./../install/g6.html#prerequisites">paramètres recommandés</a> et désactivez le Mode développeur.</li><li>La communication avec l&#39;émetteur a lieu une fois toutes les 5 minutes : après avoir modifié un paramètre, attendez un cycle de lecture complet avant d&#39;en juger l&#39;effet sur la page d&#39;état.</li><li>Vérifiez que l&#39;émetteur est activé et qu&#39;aucun autre téléphone ou appareil n&#39;est actuellement réglé pour collecter ses données (déconnectez-le si c&#39;est le cas).</li><li>Consultez la <a href="./systemstatus.html">page Dex Status</a>. Si une commande est bloquée dans la file d&#39;attente, elle doit disparaître au cycle de lecture suivant ; sinon, <a href="#transmitter-queue-stuck">videz la file d&#39;attente</a>.</li><li>Si la page d&#39;état affiche « Deep sleeping errors » ou « Checking Auth errors » avec une durée « Last Connected » toujours inférieure à 5 minutes, appuyez sur <strong>Oublier ce périphérique</strong> dans la page d&#39;état classique, revenez à la page Dex Status et acceptez la nouvelle demande d&#39;appairage qui suit (sous Android 9 ou antérieur, aucune demande n&#39;apparaît : l&#39;appairage se fait automatiquement). S&#39;il ne se connecte toujours pas, <a href="#triggering-a-pair-request-manually">déclenchez une demande d&#39;appairage</a> manuellement.</li><li>S&#39;il n&#39;y a pas de déconnexion et que la page d&#39;état affiche « OK ** days » pour l&#39;état du capteur mais que vous ne recevez aucune valeur, vérifiez que la session xDrip elle-même est démarrée : appuyez sur Démarrer le capteur et saisissez le code de calibration affiché sur la page d&#39;état (cela n&#39;affecte pas une session G6 déjà en cours).</li><li>Si cela ne fonctionne toujours pas, désactivez la collecte dans xDrip, installez l&#39;application Dexcom et essayez avec elle. Si l&#39;application Dexcom se connecte sans problème, merci de le signaler : cela nous indique que le problème vient de xDrip et non de l&#39;émetteur.</li></ol><p>Si vous avez de la connectivité et des valeurs mais qu&#39;elles se coupent de temps en temps, consultez plutôt <a href="#intermittent-connectivity">Connectivité intermittente</a>.</p><h2 id="intermittent-connectivity" tabindex="-1">Connectivité intermittente <a class="header-anchor" href="#intermittent-connectivity" aria-label="Permalink to &quot;Connectivité intermittente {#intermittent-connectivity}&quot;">​</a></h2><p>xDrip scanne toutes les 5 minutes pour rester connecté et fonctionne en arrière-plan le reste du temps pour économiser la batterie. Les versions récentes d&#39;Android (11+) et les fonctions d&#39;économie d&#39;énergie des fabricants de téléphones peuvent perturber ce fonctionnement, c&#39;est pourquoi des problèmes de connectivité initiale sont fréquents sur les Android récents.</p><ul><li>Utilisez au moins la version stable actuelle de xDrip, et partez des <a href="./../install/g6.html#prerequisites">paramètres recommandés</a>.</li><li>Consultez les conseils propres à la marque de votre téléphone sur <a href="https://dontkillmyapp.com/" target="_blank" rel="noreferrer">dontkillmyapp.com</a>.</li><li><strong>Pixel</strong> : désactiver l&#39;optimisation de la batterie demande plus que « Autoriser l&#39;utilisation en arrière-plan » : appuyez sur la note affichée et choisissez <strong>Sans restriction</strong>.</li><li><strong>Xiaomi</strong> : l&#39;optimisation de la batterie peut se réactiver discrètement après chaque redémarrage ; il faudra peut-être la désactiver à chaque fois.</li><li><strong>Unihertz</strong> : Paramètres Android → Smart Assist → Power Save Manager, et ajoutez xDrip à la liste blanche.</li><li><strong>Cubot</strong> (par ex. KingKong Mini) : ouvrez l&#39;application DuraSpeed fournie et retirez xDrip de ses restrictions d&#39;économie d&#39;énergie.</li></ul><p>Si les déconnexions continuent, essayez ceci, une chose à la fois : activez Contournement de jumelage spécial (cela peut aider même sur des téléphones autres que Samsung), essayez de désactiver Réduire le scan et, sur les appareils Samsung, essayez d&#39;activer Faire confiance à Auto-Connect dans les <a href="./../use/bluetooth.html">Paramètres Bluetooth</a>.</p><h2 id="understanding-the-dex-status-page" tabindex="-1">Comprendre la page Dex Status <a class="header-anchor" href="#understanding-the-dex-status-page" aria-label="Permalink to &quot;Comprendre la page Dex Status {#understanding-the-dex-status-page}&quot;">​</a></h2><p>Ouvrez-la depuis le menu en haut à gauche → <a href="./systemstatus.html">État du système</a>, puis faites glisser jusqu&#39;à la page « Dex Status ».</p><p>La connectivité est bonne si : une ligne « Last Connected: » est présente, sa valeur reste inférieure à 5 minutes lorsque vous êtes près du téléphone, elle augmente puis revient à 0 à chaque cycle d&#39;environ 5 minutes, et il n&#39;y a aucun message comme « Hunting Transmitter », « Scanning Error », « Waiting Connect Errors », « Checking Auth Errors » ou « Deep Sleeping Errors ». Chacun de ces messages, ou une valeur « Last Connected » qui ne se comporte pas comme décrit, signale une déconnexion : résolvez-la avant d&#39;envoyer la moindre commande (démarrer, arrêter, calibrer, réinitialisation matérielle).</p><p>xDrip reflète ce que l&#39;émetteur signale une fois toutes les 5 minutes (un système d&#39;échantillonnage-blocage) : après tout changement ou toute commande, laissez passer un cycle complet (ou deux) avant de tirer des conclusions, ne jugez pas en consultant la page d&#39;état toutes les quelques secondes.</p><div class="info custom-block"><p class="custom-block-title">Reprendre une session déjà démarrée ailleurs</p><p>Si une session est déjà en cours (démarrée depuis un autre téléphone, une autre application ou un dispositif médical), vous n&#39;avez pas besoin d&#39;en démarrer une nouvelle dans xDrip : rétablissez simplement la connectivité comme ci-dessus et soyez patient, la reprise peut prendre 10 à 15 minutes. Cela ne concerne pas le G7/ONE+ (qui démarrent toujours automatiquement). Pour le G6/ONE, si le code de calibration affiché sur la page Dex Status semble faux ou absent, ignorez-le : c&#39;est l&#39;émetteur qui a besoin du bon code, pas xDrip, et cela ne compte à nouveau que si vous démarrez un capteur réellement neuf.</p></div><p>L&#39;ID de l&#39;émetteur affiché sur cette page est propre à votre émetteur : faites attention à qui vous le communiquez, et masquez-le sur les captures d&#39;écran avant de les publier pour demander de l&#39;aide ; personne n&#39;a besoin de le voir pour vous aider.</p><h2 id="sensor-wont-start-sensor-failed-messages" tabindex="-1">Le capteur ne démarre pas / messages « sensor failed » <a class="header-anchor" href="#sensor-wont-start-sensor-failed-messages" aria-label="Permalink to &quot;Le capteur ne démarre pas / messages « sensor failed » {#sensor-wont-start-sensor-failed-messages}&quot;">​</a></h2><p>La plupart de ces cas viennent de ce que l&#39;émetteur n&#39;est pas certain qu&#39;il s&#39;agit d&#39;un véritable démarrage de nouveau capteur :</p><ul><li>L&#39;émetteur doit rester hors de tout capteur pendant au moins <strong>10 minutes</strong> avant d&#39;en démarrer un nouveau. Une erreur courante consiste à poser le nouveau capteur pendant que l&#39;ancien fonctionne encore, à arrêter l&#39;ancien, puis à clipser aussitôt l&#39;émetteur dans le nouveau capteur : comme il n&#39;est jamais resté 10 minutes dehors, l&#39;émetteur considère cela comme une tentative de redémarrage et met le nouveau capteur en échec avec une erreur.</li><li>Vérifiez que vous avez une <a href="#understanding-the-dex-status-page">connectivité correcte</a> avant de tenter le démarrage ; sinon, réglez d&#39;abord ce problème plutôt que de répéter démarrage/arrêt.</li><li>Si vous obtenez un message « sensor start failed », patientez plutôt que de réessayer sans cesse : des tentatives répétées sans traiter le problème sous-jacent de connectivité ou de timing ont tendance à aggraver la situation.</li></ul><h2 id="transmitter-queue-stuck" tabindex="-1">File d&#39;attente de l&#39;émetteur bloquée <a class="header-anchor" href="#transmitter-queue-stuck" aria-label="Permalink to &quot;File d&#39;attente de l&#39;émetteur bloquée {#transmitter-queue-stuck}&quot;">​</a></h2><p>L&#39;émetteur n&#39;écoute que brièvement une fois toutes les 5 minutes ; le reste du temps, il reste silencieux pour économiser sa batterie. Toute commande que vous envoyez (Démarrer le capteur, Arrêter le capteur, Calibrer) attend dans une file jusqu&#39;à la fenêtre suivante : vous la verrez listée sur la page Dex Status. Tant qu&#39;elle y figure, l&#39;émetteur ne l&#39;a pas encore reçue : n&#39;envoyez donc pas d&#39;autre commande par-dessus, et surtout pas tant que vous n&#39;avez pas une connectivité correcte, sinon vous risquez d&#39;être complètement bloqué.</p><p>Si une commande attend dans la file depuis plus de 5 minutes et que vous ne parvenez pas à établir la connectivité, videz la file :</p><ol><li>Appuyez sur le symbole de la pipette (traitement) sur l&#39;écran principal.</li><li>Faites un appui long sur l&#39;icône du micro en bas à droite pour obtenir un champ de saisie de texte au lieu de la saisie vocale.</li><li>Tapez <code>clear transmitter queue</code> et validez.</li></ol><p>Ne videz pas la file simplement parce qu&#39;une commande y attend normalement après que vous l&#39;avez envoyée : c&#39;est le comportement attendu, et la vider empêcherait la commande d&#39;être jamais appliquée.</p><h2 id="triggering-a-pair-request-manually" tabindex="-1">Déclencher manuellement une demande d&#39;appairage <a class="header-anchor" href="#triggering-a-pair-request-manually" aria-label="Permalink to &quot;Déclencher manuellement une demande d&#39;appairage {#triggering-a-pair-request-manually}&quot;">​</a></h2><ol><li>Paramètres → ID de l&#39;émetteur Dexcom. Notez la valeur actuelle (écrivez-la ou faites une capture d&#39;écran).</li><li>Remplacez le dernier caractère par n&#39;importe quel autre et validez.</li><li>Remettez la valeur correcte et validez.</li><li>Allez sur la <a href="./systemstatus.html">page Dex Status</a> : vous devriez voir « Hunting Transmitter » en rouge.</li><li>Dans les 5 minutes, vous devriez recevoir une demande d&#39;appairage sous Android 10+ : acceptez-la. Sous Android 9 ou antérieur, l&#39;appairage se fait automatiquement sans demande visible.</li><li>Si votre écran est verrouillé à l&#39;arrivée de la notification de demande, déverrouillez-le, déroulez le volet des notifications et acceptez-la depuis là.</li></ol><h2 id="how-strong-is-the-transmitter-signal" tabindex="-1">Quelle est la force du signal de l&#39;émetteur ? <a class="header-anchor" href="#how-strong-is-the-transmitter-signal" aria-label="Permalink to &quot;Quelle est la force du signal de l&#39;émetteur ? {#how-strong-is-the-transmitter-signal}&quot;">​</a></h2><p>Si l&#39;émetteur n&#39;émet pas réellement, aucune configuration de xDrip ne pourra y remédier : un scanner Bluetooth permet de le vérifier indépendamment de xDrip.</p><ol><li>Installez une application de scanner Bluetooth à scan continu (par ex. « BLE Scanner ») sur n&#39;importe quel téléphone Android ; ce n&#39;est pas forcément celui qui fait tourner xDrip. Méfiez-vous des publicités affichées dans ces applications.</li><li>Accordez les autorisations demandées, gardez l&#39;émetteur dans la même pièce et laissez le scan tourner.</li><li>Cherchez un appareil nommé <code>Dexcom**</code> (les deux derniers caractères du numéro de série de l&#39;émetteur) pour le G6/ONE, ou <code>DXCM**</code>/<code>DX02**</code>/<code>DX04**</code> (suffixe aléatoire) pour le G7/ONE+.</li><li>Notez le nombre négatif de force du signal affiché à côté ; vous devrez peut-être attendre jusqu&#39;à 5 minutes qu&#39;une ligne en gras (actuelle) apparaisse.</li><li>S&#39;il n&#39;apparaît jamais, l&#39;émetteur n&#39;émet pas du tout. S&#39;il apparaît, communiquez le nom de l&#39;appareil et ce nombre à la personne qui vous aide au débogage.</li></ol><h2 id="how-good-is-the-battery" tabindex="-1">Quel est l&#39;état de la batterie ? <a class="header-anchor" href="#how-good-is-the-battery" aria-label="Permalink to &quot;Quel est l&#39;état de la batterie ? {#how-good-is-the-battery}&quot;">​</a></h2><p>Les piles des émetteurs se dégradent pendant le stockage, même sans utilisation : c&#39;est pourquoi la boîte indique à la fois une date de fabrication et une date de péremption. Sur la <a href="./systemstatus.html">page Dex Status</a>, vous verrez deux tensions, Voltage A et Voltage B. Elles varient d&#39;un émetteur à l&#39;autre, mais lorsqu&#39;une pile approche de sa fin de vie, la Voltage B commence à baisser de façon régulière et continue : il est utile de la surveiller au fil de la vie de l&#39;émetteur si les valeurs commencent à sembler peu fiables à l&#39;approche de la fin prévue de sa pile.</p><h2 id="transmitter-warranty" tabindex="-1">Garantie de l&#39;émetteur <a class="header-anchor" href="#transmitter-warranty" aria-label="Permalink to &quot;Garantie de l&#39;émetteur {#transmitter-warranty}&quot;">​</a></h2><p>Un émetteur est sous garantie si les deux conditions suivantes sont remplies : la date limite d&#39;utilisation / d&#39;expédition indiquée sur la boîte n&#39;était pas dépassée lorsque vous l&#39;avez démarré (ou reçu), et vous avez commencé à l&#39;utiliser dans les 5 mois suivant sa réception. La garantie couvre 90 jours ininterrompus de fonctionnement correct. Pour cette raison, inutile de stocker des émetteurs : la pile vieillit quoi qu&#39;il arrive, et la garantie peut expirer avant que vous n&#39;utilisiez l&#39;émetteur de réserve.</p><h2 id="hard-reset" tabindex="-1">Réinitialisation matérielle <a class="header-anchor" href="#hard-reset" aria-label="Permalink to &quot;Réinitialisation matérielle {#hard-reset}&quot;">​</a></h2><p>Un G6 ne peut être réinitialisé (hard reset) via xDrip que si son firmware est en version 1.6.5.25 ou antérieure ; les firmwares plus récents ne peuvent pas être réinitialisés de cette façon. Une réinitialisation matérielle remet à zéro le compteur de jours de l&#39;émetteur sur la page d&#39;état ; ne la faites qu&#39;en l&#39;absence de session active (par ex. après l&#39;arrêt d&#39;un capteur, avant de démarrer le suivant).</p><ol><li>Vérifiez que vous avez une connectivité correcte avec l&#39;émetteur et désactivez l&#39;application Dexcom (xDrip et l&#39;application Dexcom ne peuvent pas collecter tous les deux depuis le même émetteur).</li><li>Sur l&#39;écran principal, appuyez sur le symbole de la pipette (traitement).</li><li>Faites un appui long sur l&#39;icône du micro en bas à droite pour obtenir un champ de texte.</li><li>Tapez <code>Hard Reset Transmitter</code> et validez : un message indique que la tentative va être effectuée. Ne fermez pas xDrip ; la commande doit encore parvenir à l&#39;émetteur.</li><li>Surveillez la page d&#39;état : l&#39;envoi peut prendre jusqu&#39;à 5 minutes. Un avertissement peut indiquer un possible échec ; dans ce cas, redémarrez votre téléphone ou forcez l&#39;arrêt de xDrip puis relancez-le.</li><li>Retirez l&#39;émetteur de la liste Android des appareils Bluetooth précédemment connectés.</li></ol><p>Si vous comptez continuer à utiliser l&#39;émetteur ensuite, activez-le à nouveau comme s&#39;il était neuf.</p><h2 id="restarting-a-sensor-beyond-its-normal-session" tabindex="-1">Redémarrer un capteur au-delà de sa session normale <a class="header-anchor" href="#restarting-a-sensor-beyond-its-normal-session" aria-label="Permalink to &quot;Redémarrer un capteur au-delà de sa session normale {#restarting-a-sensor-beyond-its-normal-session}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Lisez toute cette section avant de vous lancer</p><p>Le redémarrage n&#39;est pas approuvé par le fabricant et comporte de vrais risques. Les valeurs seront nettement (et de façon prévisible) trop hautes juste après le préchauffage du redémarrage : si vous corrigez cela avec de l&#39;insuline, ou si vous utilisez une boucle fermée sans l&#39;ouvrir au préalable, vous risquez de provoquer une hypoglycémie.</p></div><p>Si le firmware de l&#39;émetteur (affiché sur la page Dex Status) est en version 1.6.5.25 ou antérieure, vous pouvez utiliser le redémarrage préventif de xDrip et sauter tout ceci : il redémarre automatiquement le capteur pour vous. Sinon, si vous voulez faire fonctionner le <em>même</em> capteur au-delà de sa session normale de 10 jours, voici comment faire, avec le code de calibration d&#39;origine (les tentatives de redémarrage sans code font l&#39;objet de davantage de signalements de dysfonctionnement) :</p><ol><li>Assurez-vous d&#39;abord que la connectivité est solide : redémarrer ne réglera pas un problème de connectivité sous-jacent, et rien ne vous oblige à redémarrer avant le 10e jour, seulement si vous le choisissez.</li><li>Appuyez sur Arrêter le capteur (menu en haut à gauche), même s&#39;il est déjà arrêté et que Arrêter le capteur est la seule option affichée. Attendez que la file d&#39;attente se vide sur la page d&#39;état (~5 minutes) avant de continuer : vous verrez alors « Sensor: Stopped ».</li><li><a href="#removing-a-transmitter-without-damaging-the-sensor">Retirez l&#39;émetteur sans endommager le capteur</a>.</li><li>Attendez au moins 10 minutes avec l&#39;émetteur retiré.</li><li>Remettez l&#39;émetteur en place et utilisez Démarrer le capteur, en saisissant à nouveau le code de calibration <em>d&#39;origine</em>.</li></ol><p>Après le préchauffage de 2 heures, attendez-vous à des valeurs nettement trop hautes : l&#39;émetteur pense en effet être au premier jour d&#39;un capteur neuf, alors que la réaction réelle de votre corps au capteur est celle d&#39;un capteur posé depuis plusieurs jours. Vous devrez calibrer avec soin : ne corrigez pas plus de 20 % à la fois, espacez les calibrations d&#39;au moins 25 minutes (45 pour une troisième), et uniquement lorsque la tendance est plate ; sinon vous risquez une erreur de calibration confuse. Vous verrez « Received backfill packet out of sequence » dans les journaux pendant ce temps ; c&#39;est normal et peut être ignoré. Comme pour tout capteur vieillissant, continuez ensuite à comparer de temps en temps avec un lecteur de glycémie.</p><h2 id="changing-the-bluetooth-slot-advanced-not-recommended" tabindex="-1">Changer le slot Bluetooth (avancé, déconseillé) <a class="header-anchor" href="#changing-the-bluetooth-slot-advanced-not-recommended" aria-label="Permalink to &quot;Changer le slot Bluetooth (avancé, déconseillé) {#changing-the-bluetooth-slot-advanced-not-recommended}&quot;">​</a></h2><p>Un émetteur G6 dispose de deux slots de communication : c&#39;est ce qui permet d&#39;utiliser une pompe t:slim <em>et</em> de voir les valeurs dans xDrip, ou d&#39;utiliser ensemble un récepteur Dexcom et xDrip. xDrip utilise par défaut le slot 2 ; une pompe t:slim et le récepteur Dexcom utilisent tous deux le slot 1.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Ce paramètre est toujours caché derrière le Mode développeur, car les tests ont donné des résultats inattendus, dont des émetteurs désactivés définitivement. Il n&#39;est actuellement pas recommandé.</p></div><p>Si vous voulez tout de même le modifier : activez le <a href="./../use/misc.html#engineering-mode">Mode développeur</a>, puis Paramètres → Paramètres de débogage Dexcom → « Manual Slot Number », et réglez-le sur <code>1</code> pour forcer le slot non utilisé par défaut (désactiver le Mode développeur rétablit la valeur par défaut). Deux applications collectrices utilisant les deux slots différents ne peuvent pas fonctionner sur le même téléphone.</p><h2 id="removing-a-transmitter-without-damaging-the-sensor" tabindex="-1">Retirer un émetteur sans endommager le capteur <a class="header-anchor" href="#removing-a-transmitter-without-damaging-the-sensor" aria-label="Permalink to &quot;Retirer un émetteur sans endommager le capteur {#removing-a-transmitter-without-damaging-the-sensor}&quot;">​</a></h2><p>Normalement, une fois le capteur décollé, vous l&#39;ouvrez, sortez l&#39;émetteur et jetez le capteur. Voici comment retirer l&#39;émetteur en laissant le capteur intact et toujours en place sur votre corps, par exemple pour le transférer sur un capteur neuf.</p><p>Ne touchez pas les contacts de l&#39;émetteur ni ceux du capteur pendant l&#39;opération.</p><p>Le capteur possède deux ergots qui s&#39;accrochent sur les côtés de l&#39;émetteur, maintenus sous pression par la matière souple à l&#39;intérieur du boîtier du capteur. Pour les libérer, il vous faut un objet fin et solide pour écarter délicatement chaque ergot de l&#39;émetteur : découpez une petite bande dans l&#39;emballage plastique d&#39;un capteur de réserve et arrondissez ses coins aux ciseaux pour en faire un outil simple (tenez-le hors de portée des enfants et des animaux : risque d&#39;étouffement pour les petites mains).</p><p>Insérez délicatement l&#39;extrémité la plus large et arrondie de la bande entre le capteur et l&#39;émetteur, juste à l&#39;endroit d&#39;un ergot, jusqu&#39;à sentir ou entendre un clic de libération. La matière comprimée à l&#39;intérieur repousse alors d&#39;elle-même l&#39;émetteur de ce côté : inutile de faire davantage levier, évitez juste d&#39;appuyer sur le dessus de l&#39;émetteur, ce qui le remettrait en place. Recommencez de l&#39;autre côté, et l&#39;émetteur se dégage.</p><h2 id="what-not-to-do" tabindex="-1">Ce qu&#39;il ne faut pas faire <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;Ce qu&#39;il ne faut pas faire {#what-not-to-do}&quot;">​</a></h2><ul><li>Ne sortez pas un émetteur de sa boîte et ne touchez pas ses contacts avant d&#39;être prêt à l&#39;utiliser : le compteur de jours démarre immédiatement et ne peut pas être mis en pause.</li><li>Ne jetez pas le film adhésif de protection d&#39;un capteur avant d&#39;avoir noté le code de calibration qui y est imprimé.</li><li>Ne faites pas de pré-trempage d&#39;un capteur (l&#39;insérer bien avant de le démarrer dans xDrip) : cela perturbe la calibration d&#39;usine.</li><li>Ne démarrez pas un capteur si l&#39;émetteur n&#39;est pas resté hors de tout capteur pendant au moins 10 minutes.</li><li>Ne corrigez pas plus de 20 % d&#39;une valeur en une seule calibration.</li><li>N&#39;arrêtez pas un capteur simplement parce que vous pensez pouvoir le redémarrer facilement : il existe presque toujours une meilleure option que l&#39;arrêt.</li><li>Lorsque vous changez de téléphone, pensez à désactiver la collecte sur l&#39;ancien, sinon les deux téléphones se disputeront la connexion.</li><li>Ne tentez pas un <a href="#restarting-a-sensor-beyond-its-normal-session">redémarrage</a> sans en comprendre et en accepter les risques : il n&#39;est pas approuvé par le fabricant et les valeurs seront fausses pendant un certain temps ensuite.</li></ul><h2 id="ob1-debugging-logs" tabindex="-1">Journaux de débogage OB1 <a class="header-anchor" href="#ob1-debugging-logs" aria-label="Permalink to &quot;Journaux de débogage OB1 {#ob1-debugging-logs}&quot;">​</a></h2><p>Ceci s&#39;applique aussi bien au G6, ONE, G7 qu&#39;au ONE+ : ils utilisent tous le même collecteur OB1, qui n&#39;enregistre que très peu de détails par défaut. Si un développeur vous demande des journaux détaillés pour dépanner un problème de connexion, activez d&#39;abord la journalisation OB1 complète.</p><p>Le plus simple est de scanner ce QR code avec Paramètres, <a href="./../use/copysettings.html#auto-configure">Configuration automatique</a> et d&#39;accepter l&#39;importation. Il ne modifie qu&#39;un seul paramètre, Balises supplémentaires pour le log.</p><p>QR code - Cliquez sur l&#39;image pour l&#39;agrandir</p><p><a href="../../troubleshoot/images/qr_ob1_debug.png"><img src="'+t+'" style="zoom:50%;"></a></p><p>Vous pouvez aussi saisir les balises à la main :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../use/lesscommon.html#extra-logging-settings">Paramètres de logs supplémentaires</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Balises supplémentaires pour le log</p><p> Ob1G5CollectionService:v,Ob1G5StateMachine:v</p></div><p>Ensuite :</p><ul><li>Attendez que le problème se produise réellement avant d&#39;envoyer les journaux. Activer la journalisation seule ne capture encore rien d&#39;utile.</li><li>Ouvrez le <a href="./../use/3dotsmenu.html#events-log">Journal des événements</a> depuis le menu à 3 points, appuyez sur Télécharger les Logs et ajoutez une note identifiant l&#39;appareil afin de pouvoir faire le lien lorsque vous signalez le problème.</li><li>Désactivez-la ensuite : videz le champ Balises supplémentaires pour le log et validez. Sinon, elle continue à générer un gros volume de journaux supplémentaires.</li></ul>',62)])])}const b=r(l,[["render",o]]);export{f as __pageData,b as default};
